const output = [];
let idx = 0;   // counter for unique correlation IDs

for (const item of $input.all()) {
  const organic = item.json.organic || [];
  const keyword = item.json.searchParameters?.q || "";
  for (const r of organic) {
    if (!r.link) continue;
    const website = r.link
      .replace(/^https?:\/\//, "")
      .replace(/^www\./, "")
      .split("/")[0];

    // Build homepage URL (protocol + host only)
    let homepageUrl = "";
    try {
      const u = new URL(r.link);
      homepageUrl = `${u.protocol}//${u.host}`;
    } catch (e) {
      homepageUrl = `https://${website}`;
    }

    output.push({
      json: {
        keyword,
        title: r.title,
        website,
        url: r.link,          // specific page (contact-us / write-for-us)
        originalUrl: r.link,  // reference for Website Analyzer node
        homepageUrl,          // used for homepage fetch
        snippet: r.snippet || "",
        correlationId: `${idx}-${website}`   // unique ID to safely merge branches later
      },
    });
    idx++;   // increment counter after each item
  }
}
return output;

const allItems = $input.all();
let results = [];

// Broader keyword list — covers common variations across websites
const guestPostKeywords = /write-for-us|write-with-us|guest-post|guest-posting|guest-blog|guest-author|submit-post|submit-article|submit-content|submission-guidelines|submission-guideline|author-guidelines|contributor-guidelines|general-instructions|content-guidelines|contribute|become-author|become-a-contributor|pitch-us|pitch-your|get-published|publish-with-us/i;

for (let i = 0; i < allItems.length; i++) {
  const current = allItems[i].json;

  const website = current.website || "";
  const url = current.url || "";

  // Title extracted earlier from the homepage
  const websiteTitle = (current.homeTitle || "").trim();

  // Raw HTML of the specific page (used for emails, contact, guest post, social links)
  const html = (current.data || current.pageData || "").substring(0, 300000);

  // --------------------------------------------------
  // Brand Name — use the full website title, no splitting
  // --------------------------------------------------
  let brandName = websiteTitle.trim();
  if (!brandName) {
    brandName = website.replace(/^www\./, "").replace(/\.(com|net|org|io|co|ai)$/i, "");
  }

  // --------------------------------------------------
  // Extract Emails
  // --------------------------------------------------
  const emailRegex = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
  let emails = html.match(emailRegex) || [];
  emails = [...new Set(emails.map(e => e.toLowerCase()))];
  emails = emails.filter(email =>
    !(
      email.endsWith(".png") || email.endsWith(".jpg") || email.endsWith(".jpeg") ||
      email.endsWith(".svg") || email.endsWith(".gif") || email.endsWith(".webp") ||
      email.includes("example.com") || email.includes("yourdomain") || email.includes("email.com") ||
      email.includes("domain.com") || email.includes("yourname") || email.includes("test.com") ||
      email.includes("sentry.io") || email.includes("wixpress.com") || email.includes("placeholder")
    )
  );

  // --------------------------------------------------
  // Extract all links once (href + visible anchor text)
  // --------------------------------------------------
  const allLinkMatches = [...html.matchAll(/<a[^>]+href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gis)];
  const allLinks = allLinkMatches.map(x => ({
    href: x[1],
    text: (x[2] || "").replace(/<[^>]+>/g, "").trim()
  }));

  // --------------------------------------------------
  // Contact Links
  // --------------------------------------------------
  const contactLinks = allLinks
    .filter(l => /contact|contact-us|get-in-touch|reach-us/i.test(l.href))
    .map(l => l.href);
  const uniqueContact = [...new Set(contactLinks)].map(link => {
    if (link.startsWith("http")) return link;
    try { return new URL(link, url).href; } catch { return link; }
  });

  // --------------------------------------------------
  // Guest Post Links — check both href AND visible text
  // --------------------------------------------------
  const guestLinks = allLinks
    .filter(l => guestPostKeywords.test(l.href) || guestPostKeywords.test(l.text))
    .map(l => l.href);

  let uniqueGuest = [...new Set(guestLinks)]
    .filter(link =>
      !link.includes("wp-json") &&
      !link.includes("oembed") &&
      !link.includes("/feed") &&
      !link.includes("xmlrpc")
    )
    .map(link => {
      if (link.startsWith("http")) return link;
      try { return new URL(link, url).href; } catch { return link; }
    });

  if (uniqueGuest.length > 3) {
    uniqueGuest = [uniqueGuest[0]];
  }

  // Fallback 1: current URL itself matches guest post keywords
  if (uniqueGuest.length === 0 && url && guestPostKeywords.test(url)) {
    uniqueGuest.push(url);
  }

  // Fallback 2: current page's own title suggests it IS the guest post page
  if (uniqueGuest.length === 0 && websiteTitle && guestPostKeywords.test(websiteTitle)) {
    uniqueGuest.push(url);
  }

  // --------------------------------------------------
  // Social Links
  // --------------------------------------------------
  function extract(pattern, excludePattern) {
    const matches = [...html.matchAll(pattern)];
    for (const m of matches) {
      if (!excludePattern || !excludePattern.test(m[0])) {
        return m[0];
      }
    }
    return "";
  }

  const linkedin = extract(/https?:\/\/(?:www\.)?linkedin\.com\/[^\s"'<>]+/gi);
  const facebook = extract(/https?:\/\/(?:www\.)?facebook\.com\/[^\s"'<>]+/gi, /\/tr\?|\/plugins\/|sharer\.php|dialog\/share/i);
  const twitter = extract(/https?:\/\/(?:www\.)?(?:twitter|x)\.com\/[^\s"'<>]+/gi, /intent\/tweet|share\?/i);
  const instagram = extract(/https?:\/\/(?:www\.)?instagram\.com\/[^\s"'<>]+/gi);
  const youtube = extract(/https?:\/\/(?:www\.)?youtube\.com\/[^\s"'<>]+/gi);

  const guestPostFound = uniqueGuest.length > 0;

  // --------------------------------------------------
  // Each email = 1 item; if no email found, still send 1 "no email" item
  // --------------------------------------------------
  if (emails.length === 0) {
    results.push({
      json: {
        website, brandName, websiteTitle, url, email: "",
        contactLink: uniqueContact.join(", "),
        guestPostLink: uniqueGuest.join(", "),
        guestPostFound,
        linkedin, facebook, twitter, instagram, youtube,
        noEmailFound: true,
        // NEW: single field for Switch node — combines guestPostFound + email presence
        emailStatus: guestPostFound ? "email_not_found" : "guest_post_not_found"
      }
    });
  } else {
    emails.forEach(email => {
      results.push({
        json: {
          website, brandName, websiteTitle, url, email,
          contactLink: uniqueContact.join(", "),
          guestPostLink: uniqueGuest.join(", "),
          guestPostFound,
          linkedin, facebook, twitter, instagram, youtube,
          noEmailFound: false,
          // NEW: single field for Switch node
          emailStatus: guestPostFound ? "email_found" : "guest_post_not_found"
        }
      });
    });
  }
}

return results;

return items.map(item => {
  let email = "";
  if (item.json.email) {
    email = item.json.email;
  } else if (Array.isArray(item.json.emails) && item.json.emails.length > 0) {
    email = item.json.emails[0];
  }

  const website = item.json.website || "";

  return {
    json: {
      ...item.json,
      uniqueId: (website + "|" + email).toLowerCase(),
    }
  };
});

const results = [];

// --------------------------------------------------
// Helper: escape brand name so it can't break the HTML
// --------------------------------------------------
function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// --------------------------------------------------
// 6 Proposal Templates (HTML formatted) — Guest Post Reseller/Broker model
// Each template takes (brand, domain, niche) so wording can reference the
// site's category when available, making every email feel less templated.
// --------------------------------------------------
const templates = [
  (brand, domain, niche) => `<p>Hi ${brand} team,</p>
<p>I work with clients who are looking to publish relevant, high-quality articles on niche-relevant websites like <strong>${domain}</strong>${niche ? ` in the ${niche} space` : ""}.</p>
<p>When a client's article matches your site's niche and audience, I'd like to place it on your website with a natural link insertion.</p>
<p>Could you let me know if you accept this kind of collaboration, and what your process/guidelines are?</p>
<p>Best regards</p>`,

  (brand, domain, niche) => `<p>Hello ${brand} team,</p>
<p>I help clients place well-suited, relevant articles on websites within their niche. I came across <strong>${domain}</strong>${niche ? `, and given your focus on ${niche}` : ""} I believe it could be a great fit for some of the content I work with.</p>
<p>If a client's article aligns well with your site's topics and audience, would you be open to publishing it with a link insertion?</p>
<p>Please let me know your requirements and the next steps.</p>
<p>Best regards</p>`,

  (brand, domain, niche) => `<p>Hi there,</p>
<p>I regularly work with clients who need their articles published on relevant, quality websites. <strong>${domain}</strong>${niche ? ` and its ${niche}-focused content` : ""} caught my attention as a strong match for some of the content I manage.</p>
<p>When I have a client with an article suited to your niche, I'd like the opportunity to place it on your site along with a relevant link.</p>
<p>Could you share how you'd like to proceed, and any guidelines for accepting such content?</p>
<p>Best regards</p>`,

  (brand, domain, niche) => `<p>Hi ${brand} team,</p>
<p>I hope this email finds you well. I run a small content placement service, and <strong>${domain}</strong> stood out${niche ? ` as a strong ${niche} resource` : ""} while I was researching sites for a current client.</p>
<p>Would you be open to publishing a well-written, relevant article with a single natural link back to my client's site?</p>
<p>Happy to share more details or a sample topic if that helps.</p>
<p>Best regards</p>`,

  (brand, domain, niche) => `<p>Hello,</p>
<p>I'm reaching out on behalf of clients who are looking for quality placements${niche ? ` in the ${niche} niche` : ""}. <strong>${domain}</strong> looks like a solid fit based on your content and audience.</p>
<p>If you're open to guest contributions with a relevant, non-spammy link, I'd love to know your submission process and any editorial guidelines.</p>
<p>Best regards</p>`,

  (brand, domain, niche) => `<p>Hi ${brand} team,</p>
<p>Quick question — do you currently accept guest articles${niche ? ` related to ${niche}` : ""} on <strong>${domain}</strong>?</p>
<p>I work with clients who need their content placed on relevant, well-maintained sites, and yours came up as a good match. Happy to send over topic ideas if you're open to it.</p>
<p>Best regards</p>`
];

// --------------------------------------------------
// Subject line variants — keeps sender emails from looking
// like a bulk blast with only the brand name swapped out.
// --------------------------------------------------
const subjectTemplates = [
  (brand) => `Guest Post Opportunity for ${brand}`,
  (brand) => `Collaboration Idea for ${brand}`,
  (brand) => `Quick Question about ${brand}`,
  (brand) => `Content Partnership – ${brand}`,
  (brand) => `Would ${brand} be open to a guest post?`,
  (brand) => `Article Placement Idea for ${brand}`
];

const dupAll = $('Duplicate Procetion (website +email)').all();
let idx = -1;
for (const item of $input.all()) {
  idx++;
  const dup = (dupAll[idx] && dupAll[idx].json) || {};
  const data = item.json;

  // AI Agent (with Structured Output Parser) nests its result under "output".
  // Fall back to top-level fields too, in case an earlier node already flattened them.
  const aiOutput = data.output || {};

  const website   = data["Website"] || data.website || dup["Website"] || "";
  const brandRaw  = aiOutput["Brand Name"] || data["Brand Name"] || website;
  const brand     = escapeHtml(brandRaw);
  const niche     = (aiOutput["Category"] || data["Category"] || "").trim();

  const rootDomain = website
    ? `https://${website.replace(/^https?:\/\//, "").replace(/^www\./, "").split("/")[0]}/`
    : "";

  // Pick a random proposal + subject template independently
  const proposalIndex = Math.floor(Math.random() * templates.length);
  const subjectIndex  = Math.floor(Math.random() * subjectTemplates.length);

  const proposal = templates[proposalIndex](brand, rootDomain, niche);
  const emailSubject = subjectTemplates[subjectIndex](brandRaw);

  results.push({
    json: {
      ...data,
      "Brand Name": brandRaw,
      "Category": niche,
      Proposal: proposal,
      emailSubject
    }
  });
}

return results;

