// Pull everything needed for the email from the earlier nodes of THIS loop iteration
const dup  = $('Duplicate Procetion (website +email)').item.json;
const prop = $('Propasal Generator').item.json;

// Alternate between Gmail account "1" and "2"
const data = $getWorkflowStaticData('global');
if (!data.gmailAccount) data.gmailAccount = "1";
const gmailAccount = data.gmailAccount;

const emailMap = {
  "1": "sender@example.com",
  "2": "sender@example.com"
};
data.gmailAccount = gmailAccount === "1" ? "2" : "1";

return {
  json: {
    "Unique ID": dup['Unique ID'],
    "Website": dup['Website'] || prop['Website'] || '',
    "Emails": dup['Emails'],
    "Brand Name": prop['Brand Name'],
    "Proposal": prop['Proposal'],
    "emailSubject": prop['emailSubject'],
    "gmailAccount": gmailAccount,
    "senderEmail": emailMap[gmailAccount]
  }
};
